  cohort_day: string;
  experiment: string;
  variant: string;
  surface: string;
  /**
   * An EventPlatform, or `unknown` when the sign-up did not say.
   */
  platform: string;
  /**
   * A PriceTierName, or `unknown` when the sign-up country is unknown.
   */
  tier: string;
  /**
   * The campaign path A or B, or `unknown`.
   */
  path: string;
  exposures: number;
  sent: number;
  delivered: number;
  opened: number;
  clicked: number;
  landing_clicked: number;
  app_open_48h: number;
  connect_7d: number;
