/**
 * One device association. The same shape backs all three lists of
 * `DeviceAssociationsResult`, and each list fills in the part of it that
 * applies: a field a list does not set is omitted from that list's rows
 * rather than sent empty.
 */
export interface DeviceAssociation {
  /**
   * The association still needs confirming. Always true on
   * `pending_adoption_devices`; on the two shared lists it is the
   * negation of the stored confirmation.
   */
  pending?: boolean;
  /**
   * The adopt code or share code the association is keyed by.
   */
  code?: string;
  /**
   * Name of the device
   */
  device_name?: string;
  /**
   * udid of the shared device. Set on `incoming_shared_devices` and
   * `outgoing_shared_devices`; a pending adoption has no client yet,
   * so it is omitted there.
   */
  client_id?: string;
  /**
   * The other network in the share -- the owner for an incoming share,
   * the guest for an outgoing one. Set on the two shared lists, and
   * omitted there too while the far side is not yet named. Never set
   * on `pending_adoption_devices`.
   */
  network_name?: string;
  /**
   * Minutes until the adopt code expires, counted from the moment the
   * request was served. Set on `pending_adoption_devices` only; a
   * share does not expire, so it is omitted on the two shared lists.
   */
  duration_minutes?: number;
}

export interface DeviceAssociationsResult {
  /**
   * devices pending adoption that need to be confirmed by the offerer
   */
  pending_adoption_devices: DeviceAssociation[];
  /**
   * devices owned by another network shared to the caller network
   */
  incoming_shared_devices: DeviceAssociation[];
  /**
   * devices owned by the caller network shared to another network
   */
  outgoing_shared_devices: DeviceAssociation[];
}

