export interface PointsLeaderboardArgs {
  /**
   * The dimension to page by
   */
  sort?: "points" | "blocks" | "streak";
  /**
   * Continues a previous page in either direction: a `next_cursor`
   * opens the page after it, a `prev_cursor` the page before it.
   * Omit for the first page. A cursor is opaque and pins the snapshot
   * and the sort; `restart: true` means its snapshot is gone.
   */
  cursor?: string;
  /**
   * Jumps to a position: the page starts at the row whose `position`
   * in this sort's total order equals `seek_rank` (1-based, clamped to
   * [1, total_ranked]). Used without a cursor; the response then
   * carries both `prev_cursor` and `next_cursor` so the jumped-to
   * window pages in both directions. `total_ranked` from any previous
   * response is the client's denominator when it turns a scroll
   * position into a rank.
   */
  seek_rank?: number;
  /**
   * Page size, default 50, max 200
   */
  limit?: number;
}

export interface PointsLeaderboardRow {
  network_id: string;
  /**
   * Present only when the network turned on points_leaderboard_public (/network/points-ranking-visibility)
   */
  network_name?: string;
  /**
   * The network's emoji tag, absent when unset; shown whether or not the name is
   */
  emoji_tag?: string;
  /**
   * true when the network name is hidden; the row is listed either way
   */
  anonymous: boolean;
  /**
   * The public name contains profanity (apps may mask it)
   */
  contains_profanity?: boolean;
  /**
   * All-time points
   */
  total_points: number;
  /**
   * Finalized epochs in which the network earned points
   */
  blocks_with_points: number;
  /**
   * Consecutive finalized epochs with points ending at the latest finalized epoch
   */
  streak: number;
  /**
   * The best streak ever (informational, never ranked)
   */
  longest_streak: number;
  rank_points: number;
  rank_blocks: number;
  rank_streak: number;
  /**
   * The row's 1-based place in the requested sort's total order.
   * Ranks tie (competition ranks), positions never do: this is the
   * `seek_rank` coordinate and the key a client keeps its loaded
   * window by.
   */
  position: number;
}

export type PointsLeaderboardMe = PointsLeaderboardRow & {
  points_leaderboard_public: boolean;
  /**
   * false when the network has no points yet
   */
  ranked: boolean;
};

export interface PointsLeaderboardResult {
  rows: PointsLeaderboardRow[];
  /**
   * Pages forward from this page's last row; absent on the last page
   */
  next_cursor?: string;
  /**
   * Pages backward from this page's first row; ABSENT (the key is
   * omitted, never null) when the page starts at position 1. Present
   * on every page reached by a cursor or a `seek_rank`.
   */
  prev_cursor?: string;
  /**
   * The cursor's snapshot is gone; reload from the top
   */
  restart?: boolean;
  /**
   * Networks ranked in the snapshot; every one of them is listed across the pages
   */
  total_ranked: number;
  snapshot_time?: string;
  /**
   * The latest finalized epoch the snapshot counts
   */
  latest_epoch: number;
  /**
   * Whether the snapshot has finalized epoch metrics. When false the
   * `blocks` and `streak` sorts are refused with an error, so a client
   * should not offer them.
   */
  epoch_metrics_available: boolean;
  me?: PointsLeaderboardMe;
  error?: {
    message: string;
  };
}

