/**
 * SEED request body - starts a new trail. seed_sig is an Ed25519
 * signature over the canonical SEED message
 * (ctx "urnetwork/verify/v1", msg_type 0x01), not over this JSON.
 */
export interface VerifySeedArgs {
  /**
   * uuid. The validator's own client_id; the server checks vpk equals this client's registered Ed25519 key.
   */
  client_id: string;
  /**
   * base64 encoded 32-byte Ed25519 validator path key.
   */
  vpk: string;
  /**
   * base64 encoded 32-byte nonce.
   */
  client_nonce: string;
  /**
   * base64 encoded 64-byte Ed25519 SEED signature.
   */
  seed_sig: string;
  /**
   * Requested trail depth. The server clamps to its allowed range.
   */
  M: number;
}

/**
 * EXTEND request body - claims the pending assigned hop. extend_sig is
 * an Ed25519 signature over the canonical EXTEND message
 * (ctx "urnetwork/verify/v1", msg_type 0x02), not over this JSON.
 */
export interface VerifyExtendArgs {
  /**
   * uuid. The validator's own client_id.
   */
  client_id: string;
  /**
   * uuid
   */
  trail_id: string;
  /**
   * The ordered confirmed hop client_ids plus the single pending hop being claimed.
   */
  trail: string[];
  /**
   * base64 encoded 64-byte Ed25519 EXTEND signature.
   */
  extend_sig: string;
}

/**
 * Non-final /verify response - the server's signed commitment to the
 * next hop. The next EXTEND submits trail + next_hop.
 */
export interface VerifyAssignResult {
  /**
   * uuid
   */
  trail_id: string;
  /**
   * base64 encoded 32-byte per-trail server nonce.
   */
  server_nonce: string;
  /**
   * The ordered confirmed hop client_ids (ids only; times are published only in the final proof).
   */
  trail: string[];
  /**
   * uuid. The newly assigned pending hop.
   */
  next_hop: string;
  /**
   * The server-clamped effective trail depth.
   */
  M: number;
  /**
   * 1-byte id of the server key that signed assign_sig. See /verify/keys.
   */
  server_key_id: number;
  /**
   * base64 encoded 64-byte Ed25519 ASSIGN signature by the server (msg_type 0x03).
   */
  assign_sig: string;
}

/**
 * Final /verify response at depth M.
 */
export interface VerifyFinalResult {
  /**
   * "complete"
   */
  status: string;
  proof: VerifyProof;
}

export interface VerifyProofHeader {
  /**
   * uuid
   */
  trail_id: string;
  /**
   * base64 encoded 32-byte per-trail server nonce.
   */
  server_nonce: string;
  /**
   * base64 encoded 32-byte Ed25519 validator path key.
   */
  vpk: string;
  /**
   * Trail depth.
   */
  M: number;
}

export interface VerifyProofHop {
  /**
   * uuid. The canonical provider at this hop.
   */
  client_id: string;
  /**
   * Server-stamped confirmation time, unix milliseconds UTC.
   */
  time_ms: number;
  /**
   * The 32-byte hash of the provider's egress IP at the subnet's
   * configured prefix granularity. Marshals on the wire as a JSON
   * array of 32 integers (a Go [32]byte), not a base64 string.
   */
  egress_ip_hash: number[];
}

/**
 * The published, non-repudiable completed trail. final_sig verifies
 * under the /verify/keys key for server_key_id (msg_type 0x04);
 * verifier_sig is the validator's depth-M EXTEND signature
 * (msg_type 0x02).
 */
export interface VerifyProof {
  header: VerifyProofHeader;
  hops: VerifyProofHop[];
  /**
   * 1-byte id of the server key that signed final_sig.
   */
  server_key_id: number;
  /**
   * The server-attested coverage of the trail (v1 = M-1, the
   * server-assigned confirmed hops with the seed excluded).
   */
  coverage: number;
  /**
   * base64 encoded 64-byte Ed25519 FINAL signature by the server.
   */
  final_sig: string;
  /**
   * base64 encoded 64-byte Ed25519 depth-M EXTEND signature by the validator.
   */
  verifier_sig: string;
}

export interface VerifyServerKey {
  /**
   * 1-byte key rotation id.
   */
  server_key_id: number;
  /**
   * base64 encoded 32-byte Ed25519 public key.
   */
  public_key: string;
}

export interface VerifyKeysResult {
  keys: VerifyServerKey[];
}

